type TextInstance=(typeof P024_NATIVE_TEXT_SOURCE.textInstances)[number];
type SceneId=(typeof P024_NATIVE_TEXT_SOURCE.domains)[number];
type SceneFrame={sceneId:SceneId;frame:number};
const textById=new Map<string,TextInstance>(P024_NATIVE_TEXT_SOURCE.textInstances.map(item=>
 [item.instanceId,item]));
function item(id:string):TextInstance{
 const found=textById.get(id);if(!found)throw Error(`P024_PRESENTATION_INSTANCE_MISSING:${id}`);
 return found;
}
function inIntervals(intervals:readonly {readonly firstFrame:number;readonly lastFrame:number}[],
 frame:number){return intervals.some(i=>i.firstFrame<=frame&&frame<=i.lastFrame);}
function unique<T>(items:readonly T[]){return [...new Set(items)];}

/** Source-evidenced reading candidates and only the source IDs safe to replace
 * for these exact active scenes. Every other static glyph remains on Canvas. */
export function p024PresentationState(state:P024State){
 const binding=P024_PRESENTATION_BINDING;
 if(!Number.isSafeInteger(state.mainFrame)||state.mainFrame<1||state.mainFrame>381)
  throw new RangeError('P024_PRESENTATION_MAIN_FRAME');
 const quizVisible=state.phase==='quiz'&&state.mainFrame===binding.source.quizFrame;
 const main=p024NativeTextState('sprite-208',state.mainFrame,{quizActive:quizVisible});
 const mainText:TextInstance[]=[...main.visibleText];
 for(const masked of [binding.paragraph,binding.question])
  if(state.mainFrame>=masked.firstFrame)mainText.push(item(masked.instanceId));
 const mainIds=new Set<string>(mainText.map(row=>row.instanceId));
 const sceneFrames:SceneFrame[]=[{sceneId:'sprite-208',frame:state.mainFrame}];
 let feedbackScene:null|{sceneId:SceneId;frame:number;visibleText:TextInstance[]} = null;
 let popupScene:null|{sceneId:SceneId;frame:1;dynamicInstanceId:string;
  dynamicSourceTextId:number;text:string|null;sourceBound:boolean} = null;
 if(state.phase==='feedback'||state.phase==='popup'){
  if(!state.feedback)throw Error('P024_PRESENTATION_FEEDBACK_MISSING');
  const sceneId=state.feedback;
  const feedback=p024NativeTextState(sceneId,state.feedbackFrame);
  feedbackScene={sceneId,frame:state.feedbackFrame,visibleText:[...feedback.visibleText]};
  sceneFrames.push({sceneId,frame:state.feedbackFrame});
  if(state.phase==='popup'){
   const popup=binding.popup.find(row=>row.feedbackId===sceneId);
   if(!popup||P024_FEEDBACK[sceneId].kind!=='wrong')
    throw Error('P024_PRESENTATION_POPUP_SCENE_INVALID');
   const selected=state.selected;
   const button=selected?P024_ANSWERS[selected].button:null;
   const expected=button===198||button===199?
    p024WrongFeedbackMessage(button,state.wrongCount):null;
   const sourceBound=expected!==null&&state.wrongText===expected;
   popupScene={sceneId:popup.popupId,frame:1,
    dynamicInstanceId:popup.dynamicInstanceId,
    dynamicSourceTextId:popup.dynamicSourceTextId,
    text:sourceBound?state.wrongText:null,sourceBound};
   sceneFrames.push({sceneId:popup.popupId,frame:1});
  }
 }
 const sourceReadyInstances=binding.gates.map(gate=>{
  const sourceReady=inIntervals(gate.readyIntervals,state.mainFrame);
  return {key:gate.key as P024GlossaryKey,context:gate.context,
   buttonInstanceId:gate.buttonInstanceId,labelInstanceId:gate.labelInstanceId,
   firstSourceReadyFrame:gate.firstFrame,sourceReady,
   // Modern companion is outside source feedback artwork; popup remains modal.
   interactionReady:sourceReady&&['main','quiz','feedback'].includes(state.phase)&&
    state.glossary===null&&state.sa==='idle'};
 });
 const glossary=(['Range','Function','Output','Set','Function table'] as const).map(key=>({key,
  sourceReady:sourceReadyInstances.some(instance=>instance.key===key&&instance.sourceReady),
  interactionReady:sourceReadyInstances.some(instance=>instance.key===key&&instance.interactionReady)}));
 const tableReady=state.mainFrame>=binding.table.firstFrame&&
  binding.table.instanceIds.every(id=>mainIds.has(id));
 const answers=quizVisible?binding.answers.map(answer=>({
  ...answer,buttonCharacterId:P024_ANSWERS[answer.label].button,
  label:item(answer.labelInstanceId).text,value:item(answer.valueInstanceId).text,
 })).filter(answer=>mainIds.has(answer.labelInstanceId)&&mainIds.has(answer.valueInstanceId)):[];

 // Canvas suppresses definitions by sourceTextId. A source ID is safe only if
 // every currently active instance of that ID in every currently rendered
 // scene is represented by the same native-owned text. This deliberately
 // retains transient duplicates, answer glyphs and unaudited feedback art.
 const active=sceneFrames.flatMap(scene=>P024_NATIVE_TEXT_SOURCE.textInstances.filter(row=>
  row.kind==='static-text'&&row.domainId===scene.sceneId&&
  row.firstPlacementFrame<=scene.frame&&scene.frame<row.lastFrameExclusive));
 const candidateGroups:{name:'table'|'paragraph'|'question';ids:string[]}[]=[
  {name:'table',ids:tableReady?[...binding.table.instanceIds]:[]},
  {name:'paragraph',ids:state.mainFrame>=binding.paragraph.firstFrame?
   [binding.paragraph.instanceId]:[]},
  {name:'question',ids:state.mainFrame>=binding.question.firstFrame?
   [binding.question.instanceId]:[]},
 ];
 const nativeOwned:Record<'table'|'paragraph'|'question',string[]>={table:[],paragraph:[],question:[]};
 let eligible=candidateGroups.filter(group=>group.ids.length&&group.ids.every(id=>mainIds.has(id)));
 // A group can share one text definition with another group. Repeat after
 // removing any unsafe group so no surviving ID relies on an unowned copy.
 while(true){
  const selected=new Set(eligible.flatMap(group=>group.ids));
  const next=eligible.filter(group=>unique(group.ids.map(id=>item(id).sourceTextId))
   .every(character=>active.filter(row=>row.sourceTextId===character)
    .every(row=>selected.has(row.instanceId))));
  if(next.length===eligible.length)break;
  eligible=next;
 }
 for(const group of eligible)nativeOwned[group.name]=group.ids;
 const ownedIds=unique(Object.values(nativeOwned).flat());
 const suppressibleSourceTextIds=unique(ownedIds.map(id=>item(id).sourceTextId)).sort((a,b)=>a-b);
 return {
  locale:state.locale,sourceLanguage:binding.sourceLanguage,
  localePolicy:binding.localePolicy,phase:state.phase,
  currentSceneIds:sceneFrames.map(scene=>scene.sceneId),sceneFrames,
  main:{sceneId:'sprite-208' as const,frame:state.mainFrame,visibleText:mainText,
   table:{sourceGeometryReady:tableReady,instanceIds:binding.table.instanceIds,
    nativeOwned:nativeOwned.table.length===binding.table.instanceIds.length},
   paragraphCompleteInk:state.mainFrame>=binding.paragraph.firstFrame,
   questionCompleteInk:state.mainFrame>=binding.question.firstFrame,
   answers},
  feedbackScene,popupScene,glossary,glossaryInstances:sourceReadyInstances,
  ownership:{nativeOwnedInstanceIds:ownedIds,nativeOwnedByRole:nativeOwned,
   suppressibleSourceTextIds,sceneScoped:true,
   fallbackActiveInstanceIds:active.filter(row=>!ownedIds.includes(row.instanceId))
    .map(row=>row.instanceId)},
 };
}
